public class DstCheck {
  public static void main(String[] a) {
    ZoneId ny = ZoneId.of("America/New_York");
    for (LocalDate issue : new LocalDate[]{LocalDate.of(2026,2,2), LocalDate.of(2026,2,14)}) {
      Instant oldWay = issue.atStartOfDay(ny).toInstant().plus(Duration.ofDays(30));
      Instant newWay = issue.plusDays(30).atStartOfDay(ny).toInstant();
      System.out.printf("issue=%s  old(buggy)=%s  new(fixed)=%s  differ=%s%n",
          issue, oldWay, newWay, !oldWay.equals(newWay));
    }
    System.out.println("DST transition 2026: " + ny.getRules().nextTransition(Instant.parse("2026-01-01T00:00:00Z")));
  }
}
